/**
 * CoolProp WASM React Wrapper
 * 
 * React-optimized wrapper for CoolProp WASM module with hooks and utilities
 * for easy integration in React applications.
 */

import Module from './coolprop.js';

let coolpropInstance = null;
let initPromise = null;

/**
 * Initialize CoolProp WASM module (singleton pattern)
 * @returns {Promise<Object>} The initialized CoolProp module
 */
export async function initCoolProp() {
    if (coolpropInstance) {
        return coolpropInstance;
    }
    
    if (initPromise) {
        return initPromise;
    }
    
    initPromise = Module().then(instance => {
        coolpropInstance = instance;
        return instance;
    });
    
    return initPromise;
}

/**
 * Get the initialized CoolProp instance
 * @returns {Object|null} The CoolProp instance or null if not initialized
 */
export function getCoolProp() {
    return coolpropInstance;
}

/**
 * PropsSI function - Direct access to property calculations
 * @param {string} output - Output property
 * @param {string} input1 - First input property name
 * @param {number} value1 - First input value
 * @param {string} input2 - Second input property name
 * @param {number} value2 - Second input value
 * @param {string} fluid - Fluid name
 * @returns {Promise<number>} Property value
 */
export async function PropsSI(output, input1, value1, input2, value2, fluid) {
    const coolprop = await initCoolProp();
    return coolprop.PropsSI(output, input1, value1, input2, value2, fluid);
}

/**
 * Create AbstractState instance
 * @param {string} backend - Backend name (e.g., 'HEOS')
 * @param {string} fluid - Fluid name or mixture
 * @returns {Promise<Object>} AbstractState instance
 */
export async function createAbstractState(backend, fluid) {
    const coolprop = await initCoolProp();
    return coolprop.factory(backend, fluid);
}

/**
 * React Hook for CoolProp initialization
 * @returns {Object} { coolprop, isLoading, error }
 */
export function useCoolProp() {
    const [state, setState] = React.useState({
        coolprop: null,
        isLoading: true,
        error: null
    });
    
    React.useEffect(() => {
        initCoolProp()
            .then(coolprop => {
                setState({
                    coolprop,
                    isLoading: false,
                    error: null
                });
            })
            .catch(error => {
                setState({
                    coolprop: null,
                    isLoading: false,
                    error
                });
            });
    }, []);
    
    return state;
}

/**
 * React Hook for property calculations
 * @param {string} output - Output property
 * @param {string} input1 - First input property name
 * @param {number} value1 - First input value
 * @param {string} input2 - Second input property name
 * @param {number} value2 - Second input value
 * @param {string} fluid - Fluid name
 * @returns {Object} { value, isLoading, error }
 */
export function useProperty(output, input1, value1, input2, value2, fluid) {
    const [state, setState] = React.useState({
        value: null,
        isLoading: true,
        error: null
    });
    
    React.useEffect(() => {
        if (value1 == null || value2 == null) {
            setState(prev => ({ ...prev, isLoading: false }));
            return;
        }
        
        setState(prev => ({ ...prev, isLoading: true, error: null }));
        
        PropsSI(output, input1, value1, input2, value2, fluid)
            .then(value => {
                setState({
                    value,
                    isLoading: false,
                    error: null
                });
            })
            .catch(error => {
                setState({
                    value: null,
                    isLoading: false,
                    error
                });
            });
    }, [output, input1, value1, input2, value2, fluid]);
    
    return state;
}

/**
 * React Hook for AbstractState management
 * @param {string} backend - Backend name
 * @param {string} fluid - Fluid name
 * @returns {Object} { state, isLoading, error, update }
 */
export function useAbstractState(backend, fluid) {
    const [hookState, setHookState] = React.useState({
        state: null,
        isLoading: true,
        error: null
    });
    
    React.useEffect(() => {
        createAbstractState(backend, fluid)
            .then(state => {
                setHookState({
                    state,
                    isLoading: false,
                    error: null
                });
            })
            .catch(error => {
                setHookState({
                    state: null,
                    isLoading: false,
                    error
                });
            });
    }, [backend, fluid]);
    
    const update = React.useCallback(async (inputPair, value1, value2) => {
        if (!hookState.state) return;
        
        try {
            const coolprop = await initCoolProp();
            hookState.state.update(inputPair, value1, value2);
            return true;
        } catch (error) {
            setHookState(prev => ({ ...prev, error }));
            return false;
        }
    }, [hookState.state]);
    
    return {
        ...hookState,
        update
    };
}

// Export constants for convenience
export const INPUT_PAIRS = {
    get PT_INPUTS() { return getCoolProp()?.input_pairs?.PT_INPUTS; },
    get QT_INPUTS() { return getCoolProp()?.input_pairs?.QT_INPUTS; },
    get PQ_INPUTS() { return getCoolProp()?.input_pairs?.PQ_INPUTS; },
    get HmolarP_INPUTS() { return getCoolProp()?.input_pairs?.HmolarP_INPUTS; },
    get HmolarT_INPUTS() { return getCoolProp()?.input_pairs?.HmolarT_INPUTS; },
    get SmolarT_INPUTS() { return getCoolProp()?.input_pairs?.SmolarT_INPUTS; },
    get DmolarT_INPUTS() { return getCoolProp()?.input_pairs?.DmolarT_INPUTS; }
};

export const PARAMETERS = {
    get iP() { return getCoolProp()?.parameters?.iP; },
    get iT() { return getCoolProp()?.parameters?.iT; },
    get iDmolar() { return getCoolProp()?.parameters?.iDmolar; },
    get iHmolar() { return getCoolProp()?.parameters?.iHmolar; },
    get iSmolar() { return getCoolProp()?.parameters?.iSmolar; },
    get iQ() { return getCoolProp()?.parameters?.iQ; }
};

// Default export
export default {
    initCoolProp,
    getCoolProp,
    PropsSI,
    createAbstractState,
    useCoolProp,
    useProperty,
    useAbstractState,
    INPUT_PAIRS,
    PARAMETERS
};